296	// directly. An action helper returns what the screen reported: an id when a row was created,
297	// true/false for whether the action went through or the screen refused it (its error element
298	// appeared). It throws when neither a result nor an error shows within the wait, so a screen that
299	// does nothing fails the test instead of passing as "refused".
300	import { expect, test, type Browser, type BrowserContext, type Locator, type Page } from '@playwright/test';
301	import { existsSync, readFileSync } from 'node:fs';
