305	const LOAD_WAIT = 30000;      // a sign-in, a sheet load or a today change: the whole sheet is re-read
306	const ERROR_GRACE = 2000;     // how long an error left over from the action before may linger
307	const AUDIT_WAIT = 3000;      // how long an audit line may lag the screen
