400	/** Poll until `done` holds (true) or `error` is visible (false); throw when neither happens.
401	 *  Each check returns as soon as it can. An error already visible at the first look after the
402	 *  click may be left over from the action before (the screen clears it when a new action is
403	 *  submitted, see README): it counts as this action's refusal once it has gone away and been
404	 *  shown again, once its text changes, or once ERROR_GRACE has passed with no result.
405	 *  `already` says `done` held BEFORE the action (watching a person already watched, saving a
406	 *  setting at its current value): then the result on screen proves nothing, and the action
407	 *  counts as taken only once ERROR_GRACE has passed with no refusal shown. */
408	async function until(page: Page, done: () => Promise<boolean>, error: Locator, what: string,
409	                     already = false): Promise<boolean> {
410	  const deadline = Date.now() + WAIT;
411	  let stale: string | null | undefined;   // text of an error visible at the first look; null if none
412	  let seenGone = false;
413	  const grace = Date.now() + ERROR_GRACE;
414	  while (Date.now() < deadline) {
415	    if (!already && await done()) return true;
416	    const visible = await error.isVisible().catch(() => false);
417	    if (stale === undefined) stale = visible ? await shown(error) : null;
418	    if (visible) {
419	      if (stale === null || seenGone || (await shown(error)) !== stale || Date.now() >= grace) return false;
420	    } else {
421	      seenGone = true;
422	    }
423	    // the state held before the action: an error still showing at the grace outranks it
424	    if (already && Date.now() >= grace && await done()) return true;
425	    await page.waitForTimeout(50);
426	  }
427	  if (await done()) return true;
428	  if (await error.isVisible().catch(() => false)) return false;
429	  throw new Error(`${what}: neither a result nor an error appeared within ${WAIT}ms`);
430	}
