462	  let cleared = false;
463	  const done = async () => {
464	    if ((await cell.count()) === 0) return false;
465	    const now = await shown(cell);
466	    if (now === '') { cleared = true; return false; }
467	    return now !== was || was === '' || cleared;
468	  };
469	  try {
470	    return (await until(page, done, error, what)) ? await shown(cell) : null;
471	  } catch (e) {
472	    if (await error.isVisible().catch(() => false)) return null;
473	    if ((await cell.count()) > 0 && (await shown(cell)) !== '') return shown(cell);
474	    throw e;
475	  }
476	}
