480	// Each sign-in gets its own browser context, so users on one sheet act independently. A context
481	// is closed once the test that opened it has finished: the test runner leaves them open, and a
482	// whole suite of open pages, each still running the app, would exhaust the machine.
483	const opened = new Map<BrowserContext, string>();   // context -> id of the test that opened it
484	
485	export async function userPage(browser: Browser, user: string, sheet: string): Promise<Page> {
486	  let owner = '';
487	  try { owner = test.info().testId; } catch { /* outside a test: nothing to tidy by */ }
488	  for (const [c, t] of opened) {
489	    if (t === owner) continue;
490	    opened.delete(c);
491	    await c.close().catch(() => { /* already gone */ });
492	  }
493	  const context = await browser.newContext();
494	  opened.set(context, owner);
495	  const page = await context.newPage();
496	  page.setDefaultTimeout(LOAD_WAIT);     // an element an action needs that never shows fails here, not at the test's limit
497	  await page.goto('/');
498	  await page.getByTestId('signin-name').fill(user);
499	  await page.getByTestId('signin-submit').click();
500	  await expect(page.getByTestId('current-user')).toHaveText(user, { timeout: LOAD_WAIT });
501	  await loadSheet(page, sheet);
502	  return page;
503	}
