511	/** Re-load the active sheet so the screen shows what the store holds now. Loading the same id
512	 *  again is not observable (the current id already reads that), so the screen first loads a
513	 *  throwaway id, which has no one on it, and waits for the person rows to go; then it loads the
514	 *  sheet again and waits for rows to show. Rows that were on screen before may rightly not come
515	 *  back (someone retired since, say), so the wait is for any row, and for every row that is back
516	 *  to carry at least the claims it had; if none shows within the wait the screen is taken as it
517	 *  is and the test's own checks decide. The show-retired box and the as-of date, which belong to
518	 *  the screen, are put back if the loads reset them. */
519	export async function refresh(page: Page): Promise<void> {
520	  const sheet = (await page.getByTestId('sheet-current-id').textContent() ?? '').trim();
521	  const before = new Map<string, number>();
522	  for (const id of await ids(rows(page), 'person-row-')) before.set(id, await claimRows(row(page, id)).count());
523	  const retired = page.getByTestId('show-retired');
524	  const showRetiredWas = (await retired.count()) > 0 ? await retired.isChecked() : null;
525	  const asofWas = await shown(page.getByTestId('sheet-asof'));
526	  const previewWas = await shown(page.getByTestId('sheet-preview'));
527	  await loadSheet(page, sheet + '-reload');
528	  await expect.poll(() => rows(page).count(), { message: 'the throwaway sheet, which has no one on it, is on screen', timeout: LOAD_WAIT }).toBe(0);
529	  await loadSheet(page, sheet);
530	  if (showRetiredWas !== null && (await retired.isChecked()) !== showRetiredWas) await retired.setChecked(showRetiredWas);
531	  if (asofWas !== '' && (await shown(page.getByTestId('sheet-asof'))) !== asofWas) await setAsOf(page, asofWas);
532	  if (previewWas !== '' && (await shown(page.getByTestId('sheet-preview'))) !== previewWas) await setPreview(page, previewWas);
533	  if (before.size === 0) return;
534	  const back = async () => {
535	    if ((await rows(page).count()) === 0) return false;
536	    for (const [id, n] of before) {
537	      const r = row(page, id);
538	      if ((await r.count()) > 0 && (await claimRows(r).count()) < n) return false;
539	    }
540	    return true;
541	  };
542	  const deadline = Date.now() + LOAD_WAIT;
543	  while (Date.now() < deadline && !(await back())) await page.waitForTimeout(50);
544	}
