644	export async function editSave(page: Page, f: PersonFields, shows?: Shows): Promise<boolean> {
645	  const id = editing.get(page);
646	  if (!id) throw new Error('editSave without editOpen');
647	  const want = typeof shows === 'string' ? { grade: shows } : (shows ?? {});
648	  const grade = want.grade ?? f.grade;                       // the grade the row shows once saved
649	  const terms = want.terms ?? f.terms;                       // the terms in force the row shows
650	  const r = row(page, id);
