1120	/** The cells an edit will be judged by, as they are before the save. */
1121	async function editedCells(c: Locator, f: ClaimFields): Promise<Record<string, string>> {
1122	  const out: Record<string, string> = {};
1123	  for (const k of Object.keys(f)) out[k] = await shown(c.getByTestId(`claim-${k}`));
1124	  return out;
