1127	/** Whether the row shows the edit: an amount, date, note or corrects cell equal to what was
1128	 *  typed; a ref or tags cell, which the app normalises, is taken as saved once the form's error
1129	 *  is not showing and the cell is no longer what it was (or the typed value, normalised, is a
1130	 *  value it could not have had before). */
1131	async function editedShows(c: Locator, f: ClaimFields, was: Record<string, string>): Promise<boolean> {
1132	  for (const [k, v] of Object.entries(f)) {
1133	    const cell = await shown(c.getByTestId(`claim-${k}`));
1134	    if (k === 'ref' || k === 'tags') {
1135	      const norm = k === 'ref' ? v.trim() : v.split(',').map((t) => t.trim().toLowerCase()).filter((t) => t)
1136	        .filter((t, i, a) => a.indexOf(t) === i).sort().join(', ');
1137	      if (cell !== norm) return false;
1138	    } else if (cell !== v) return false;
1139	  }
1140	  return true;
1141	}
